def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []
        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []
        valid.sort()
        merged = [valid[0]]
        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    # Merge both input lists
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []
    if not b_merged:
        return a_merged

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current = [[a_start, a_end]]
        for b_start, b_end in b_merged:
            new_current = []
            for c_start, c_end in current:
                if b_end <= c_start or b_start >= c_end:
                    # No overlap
                    new_current.append([c_start, c_end])
                else:
                    # There is overlap
                    if c_start < b_start:
                        new_current.append([c_start, b_start])
                    if c_end > b_end:
                        new_current.append([b_end, c_end])
            current = new_current
        result.extend(current)

    # Merge touching intervals in result
    return merge_intervals(result)

